//! The Tormach library (data/machines/tormach.toml, generated by tools/machines/tormach.py from
//! tormach.com's spec pages): real and cited, the published numbers in place, and a short job on
//! the 1100MX through the linuxcnc dialect (PathPilot is LinuxCNC-based).
use forge_machine::collide;
use forge_machine::def::{Kind, MachineDef};
use forge_machine::gcode::Control;
use forge_machine::library::{builtin_files, builtin_named};
use forge_machine::sim::{self, Cut, Setup, SimTool};

#[test]
fn tormach_records_are_real_and_cited() {
    let ms: Vec<MachineDef> = builtin_files()
        .into_iter()
        .filter(|(_, f)| f == "builtin/tormach.toml")
        .map(|(m, _)| m)
        .collect();
    assert_eq!(
        ms.len(),
        11,
        "{:?}",
        ms.iter().map(|m| &m.name).collect::<Vec<_>>()
    );
    for m in &ms {
        assert!(m.real, "{}", m.name);
        for p in m.cite_paths() {
            assert!(m.cites.iter().any(|c| c.path == p), "{}: {p}", m.name);
        }
    }
    let m = builtin_named("tormach-1100mx").unwrap();
    assert_eq!(m.kind, Kind::Vmc3);
    assert_eq!(m.joint("X").unwrap().range, Some([-457.0, 0.0])); // 18 in
    assert_eq!(m.joint("X").unwrap().rapid, Some(7620.0)); // 300 IPM (7.62 m/min)
    assert_eq!(m.joint("Z").unwrap().rapid, Some(5840.0)); // 230 IPM
    assert_eq!(m.spindles[0].rpm.unwrap()[1], 10000.0);
    assert_eq!(m.spindles[0].nose[2], 438.0); // nose to table max clearance, 17.25 in
    let r = builtin_named("tormach-24r").unwrap();
    assert_eq!(r.joint("Y").unwrap().range, Some([-1415.0, 0.0]));
    assert_eq!(r.spindles[0].rpm, Some([10000.0, 24000.0]));
    let l = builtin_named("tormach-15lx-turret").unwrap();
    assert_eq!(l.kind, Kind::Lathe);
    assert_eq!(l.turrets[0].stations, Some(8));
    assert_eq!(l.spindles[0].rpm.unwrap()[1], 3500.0);
}

#[test]
fn tormach_1100mx_job() {
    let m = builtin_named("tormach-1100mx").unwrap();
    let mut s = Setup::new(&m, Control::for_dialect(&m, "linuxcnc", 1).unwrap()).unwrap();
    // the spindle over the table centre at mid-travel: X -228.5, Y -139.5; Z word 0 at the table top
    s.wcs = vec![(54, vec![-139.5, -228.5, -438.0])];
    s.tools = vec![SimTool {
        t: 1,
        name: "flat-6".into(),
        tip: [0.0, 0.0, -80.0],
        body: vec![(3.0, 0.0, 20.0), (10.0, 20.0, 80.0)],
        cut: Cut::Mill { r: 3.0, corner: 0.0 },
    }];
    s.h = vec![(1, 80.0)];
    s.start_tool = Some(1);
    let prog = "G21 G90 G54\nG43 H1\nG0 X-50. Y0 Z30.\nG1 Z18. F600.\nX50. F1500.\nG2 X50. Y-20. I0 J-10.\nG0 Z60.\n";
    let tl = sim::simulate(prog, &s).unwrap();
    assert!(tl.violations.is_empty(), "{:?}", tl.violations);
    assert!(collide::check(&s, &tl, &[]).contacts.is_empty());
    // a feed above the published 300 IPM is clamped and reported
    let tl = sim::simulate("G21 G90 G54\nG43 H1\nG0 X-50. Y0 Z30.\nG1 X50. F9000.\n", &s).unwrap();
    assert!(!tl.violations.is_empty());
}
